#!/usr/bin/env python3
"""Builds src/data/ from research/ (RECETTE §4: data sets generated by a replayable script).

    python3 scripts/build-data.py            # all subjects
    python3 scripts/build-data.py cs wc      # some subjects

research/ holds what was read on official pages (one JSON per state and subject, with the URL of
each figure, see research/BRIEF-RECHERCHE.md). This script only normalizes shapes for the engines
and the pages: it never changes a figure. States whose data are incomplete are skipped and listed.
"""
import json, os, re, sys, glob

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
R = os.path.join(ROOT, 'research')
D = os.path.join(ROOT, 'src', 'data')
STATES = [l.split("'")[1::2] for l in open(os.path.join(D, 'states.ts')).read().split('\n') if False]
WHAT = sys.argv[1:] or ['cs', 'wc', 'alimony', 'divorce', 'probate']
skipped = []


def jload(p):
    with open(p, encoding='utf-8') as f:
        return json.load(f)


def jdump(obj, p):
    os.makedirs(os.path.dirname(p), exist_ok=True)
    with open(p, 'w', encoding='utf-8') as f:
        json.dump(obj, f, ensure_ascii=False, separators=(',', ':'))


def src(name, url):
    return {'name': name, 'url': url} if url else None


def host(url):
    m = re.match(r'https?://(?:www\.)?([^/]+)', url or '')
    return m.group(1) if m else url


# ── Child support ───────────────────────────────────────────────────────────────────────────────
INCOME_LABEL = {
    'net': 'Net income: after income taxes and mandatory deductions, as the state defines it.',
    'gross': 'Gross income before taxes, as the state guideline defines it.',
    'adjusted-gross': 'Adjusted gross income: gross income minus the deductions the guideline allows.',
    'net-resources': 'Monthly net resources: income minus taxes, FICA and the children’s health insurance (Tex. Fam. Code § 154.062).',
}
# Per-state choices read in each guideline (see research/cs/<slug>.json addOns / formula texts).
CS_OVERRIDES = {
    'california': {'addOns': {'childcare': True, 'health': False}, 'incomeLabel': 'Net disposable income: gross minus taxes actually payable, FICA, mandatory retirement, health premiums (Fam. Code § 4059).'},
    'texas': {'addOns': {'childcare': False, 'health': False}},
}


META_KEYS = {'slug', 'source', 'edition', 'period', 'columns', 'rows', 'note', 'url', 'effective', 'state', 'title',
             'retrieved', 'retrievedVia', 'fetchedVia', 'verified', 'script', 'rowCount', 'document', 'section', 'incomeBasis',
             'lookup', 'aboveMax'}


def schedule_rows(slug):
    """Rows exactly as parsed from the official table (numbers only converted), plus the other keys of
    the schedule file (`extra`: low-income tables, bands, parenting-time tables…) for the state's model."""
    p = os.path.join(R, 'cs-schedules', f'{slug}.json')
    if not os.path.exists(p):
        return None, {}, {}
    s = jload(p)
    meta = s if isinstance(s, dict) else {}
    rows = s.get('rows') if isinstance(s, dict) else s
    extra = {k: v for k, v in meta.items() if k not in META_KEYS}
    if meta.get('columns') is not None:
        extra['columns'] = meta['columns']
    def conv(x):
        if isinstance(x, (int, float)) or x is None:
            return x
        if isinstance(x, str):
            try:
                return float(x.replace(',', '').replace('$', ''))
            except ValueError:
                return x
        if isinstance(x, list):
            return [conv(y) for y in x]
        return x
    out = [conv(r) if isinstance(r, list) else r for r in (rows or [])]
    return (out or None), meta, extra


def build_cs():
    out = os.path.join(D, 'cs')
    for old in glob.glob(os.path.join(out, '*.json')):
        os.remove(old)
    for f in sorted(glob.glob(os.path.join(R, 'cs', '*.json'))):
        r = jload(f)
        slug = r['slug']
        ov = CS_OVERRIDES.get(slug, {})
        model = r.get('model')
        sch = r.get('schedule') or None
        rows, meta, extra = schedule_rows(slug)
        schedule = None
        if sch is None and rows:
            sch = {}
        if rows:
            am = (sch.get('aboveMax') or meta.get('aboveMax') or {})
            if not isinstance(am, dict): am = {'method': 'discretion', 'text': str(am)}
            method = am.get('method') or 'discretion'
            if method == 'ceiling':
                method = 'cap'
            if method not in ('percent-of-excess', 'cap', 'discretion', 'extrapolate'):
                method = 'discretion'
            lookup = sch.get('lookup') or meta.get('lookup') or 'floor'
            if lookup not in ('floor', 'nearest', 'interpolate', 'bracket'):
                lookup = 'floor'
            schedule = {
                'rows': rows, 'lookup': lookup,
                'minIncome': sch.get('minIncome') if sch.get('minIncome') is not None else rows[0][0],
                'maxIncome': sch.get('maxIncome') if sch.get('maxIncome') is not None else rows[-1][0],
                'aboveMax': {'method': method, 'pct': am.get('pct')},
                'columnFor': ov.get('columnFor'),
            }
        elif model == 'income-shares' and not os.path.exists(os.path.join(ROOT, 'src', 'lib', 'engine', 'cs', f'{slug}.ts')):
            skipped.append(f'cs/{slug}: income shares without schedule rows and without a model file')
            continue
        pc = r.get('percent')
        percent = None
        if pc and pc.get('byChildren'):
            cap = pc.get('cap')
            percent = {
                'byChildren': pc['byChildren'],
                'tiers': pc.get('tiers') if isinstance(pc.get('tiers'), list) else None,
                'cap': {'amount': cap['amount'], 'period': cap.get('period') or r['period'],
                        'appliesTo': 'combined' if 'combined' in (cap.get('appliesTo') or '') else 'obligor'} if cap and cap.get('amount') else None,
                'lowIncome': {'threshold': pc['lowIncome']['threshold'], 'byChildren': pc['lowIncome']['byChildren']} if isinstance(pc.get('lowIncome'), dict) and pc['lowIncome'].get('byChildren') else None,
            }
        sh = r.get('shared') or {}
        shared = {'method': sh.get('method') if sh.get('method') in ('cross-credit', 'percent-reduction') else 'none',
                  'thresholdOvernights': sh.get('thresholdOvernights'), 'multiplier': sh.get('multiplier'),
                  'reductionTable': sh.get('reductionTable') if isinstance(sh.get('reductionTable'), list) and all(isinstance(x, list) and len(x) == 2 for x in sh.get('reductionTable')) else None}
        if shared['method'] == 'percent-reduction' and not shared['reductionTable']:
            shared['method'] = 'none'
        if isinstance(sh.get('reductionTable'), list) and not shared['reductionTable']:
            shared['table'] = sh.get('reductionTable')  # other shapes: read by the state's model file
        if shared['method'] == 'cross-credit' and (shared['thresholdOvernights'] is None or not shared['multiplier']):
            shared['method'] = 'none'
        ao = r.get('addOns') or {}
        add = ov.get('addOns') or {'childcare': True, 'health': True}
        sources, seen = [], set()
        def addsrc(name, url):
            if url and url not in seen:
                seen.add(url); sources.append({'name': name, 'url': url})
        st = r.get('statute') or {}
        addsrc(f"{r['name']}: {st.get('cite') or 'child support guideline'}", st.get('url'))
        addsrc(f"{r['name']}: child support guidelines", r.get('guidelinesUrl'))
        if sch:
            addsrc(f"{r['name']}: official schedule of basic support obligations", sch.get('url'))
        if pc:
            addsrc(f"{r['name']}: guideline percentages", pc.get('url'))
            if pc.get('cap'):
                addsrc(f"{r['name']}: income cap of the guideline", pc['cap'].get('url'))
        if r.get('formula'):
            addsrc(f"{r['name']}: guideline formula", r['formula'].get('url'))
        addsrc(f"{r['name']}: shared parenting rule", sh.get('url'))
        addsrc(f"{r['name']}: child care and health insurance", ao.get('url'))
        addsrc(f"{r['name']}: low-income rule", (r.get('lowIncome') or {}).get('url'))
        addsrc(f"{r['name']}: when support ends", (r.get('emancipation') or {}).get('url'))
        addsrc(f"{r['name']}: official child support calculator", r.get('officialCalculatorUrl'))
        for fct in r.get('facts') or []:
            addsrc(f"{r['name']}: {host(fct.get('url'))}", fct.get('url'))
        model_text = (r.get('formula') or {}).get('text') if model in ('ca-formula', 'melson', 'bands-combined', 'other') else None
        if not model_text:
            model_text = (pc or {}).get('text') or (sch or {}).get('lookupRule') or r.get('modelName')
        li = r.get('lowIncome') or {}
        d = {
            'slug': slug, 'name': r['name'], 'abbr': r['abbr'], 'verified': r.get('verified', '2026-10-08'),
            'model': model, 'modelName': r.get('modelName'), 'incomeBasis': r.get('incomeBasis'),
            'incomeLabel': ov.get('incomeLabel') or INCOME_LABEL.get(r.get('incomeBasis'), 'Income as the state guideline defines it.'),
            'period': r.get('period', 'monthly'), 'maxChildren': r.get('maxChildren') or 6,
            'schedule': schedule, 'percent': percent, 'formula': (r.get('formula') or {}).get('params'),
            'shared': shared, 'addOns': add, 'extra': extra or None,
            'lowIncome': {'selfSupportReserve': li.get('selfSupportReserve'), 'period': li.get('period') or r.get('period', 'monthly'),
                          'minimumOrder': li.get('minimumOrder'), 'method': ov.get('lowIncomeMethod', 'text')},
            # texts
            'statute': {'name': st.get('cite') or '', 'url': st.get('url') or ''},
            'guidelinesUrl': r.get('guidelinesUrl') or st.get('url') or '',
            'officialCalculatorUrl': r.get('officialCalculatorUrl'),
            'incomeDefinition': r.get('incomeDefinition') or '',
            'modelText': model_text or '',
            'sharedText': sh.get('text') or '',
            'addOnsText': ' '.join(x for x in [ao.get('childcare'), ao.get('healthInsurance'), ao.get('text')] if isinstance(x, str)),
            'lowIncomeText': li.get('rule') or '',
            'emancipation': {'text': (r.get('emancipation') or {}).get('text') or '', 'url': (r.get('emancipation') or {}).get('url') or ''},
            'scheduleText': (sch or {}).get('lookupRule'),
            'aboveMaxText': ((sch or {}).get('aboveMax') or {}).get('text'),
            'effective': (sch or {}).get('effective') or ((pc or {}).get('cap') or {}).get('effective') or ((r.get('formula') or {}).get('params') or {}).get('operative'),
            'facts': [{'text': x['text'], 'url': x['url']} for x in r.get('facts') or [] if x.get('text') and x.get('url')],
            'sources': sources,
            'testCases': r.get('testCases') or [],
        }
        jdump(d, os.path.join(out, f'{slug}.json'))
    print('cs:', len(glob.glob(os.path.join(out, '*.json'))), 'files')


# ── Workers' comp ───────────────────────────────────────────────────────────────────────────────
def wc_basis(b):
    b = (b or '').lower()
    if 'spendable' in b:
        return 'spendable', 'Weekly spendable earnings (gross minus income taxes and FICA)'
    if 'after-tax' in b or 'after tax' in b or 'net' in b:
        return 'after-tax', 'Average weekly wage after taxes, as the state defines it'
    if 'month' in b:
        return 'monthly', 'Gross monthly wage at the time of injury'
    return 'gross', 'Gross average weekly wage before taxes'


# States whose statute sets a weekly maximum: without the figure, no page (a calculator without the cap would overstate).
WC_MAX_REQUIRED = {'kansas', 'idaho'}
# Below the minimum, read in each state's minText (research/wc/<slug>.json):
WC_MINRULE = {
    'alabama': 'actual-wage-if-lower', 'alaska': 'actual-wage-if-lower', 'delaware': 'actual-wage-if-lower',
    'florida': 'actual-wage-if-lower', 'louisiana': 'actual-wage-if-lower', 'maryland': 'actual-wage-if-lower',
    'north-dakota': 'actual-wage-if-lower', 'minnesota': 'actual-wage-if-lower', 'georgia': 'actual-wage-if-lower', 'iowa': 'actual-wage-if-lower', 'nebraska': 'actual-wage-if-lower', 'new-hampshire': 'actual-wage-if-lower', 'south-dakota': 'actual-wage-if-lower',
    'connecticut': ('pct-of-wage-if-lower', 75), 'oregon': ('pct-of-wage-if-lower', 90), 'vermont': ('pct-of-wage-if-lower', 90),
    'pennsylvania': ('pct-of-wage-if-lower', 90), 'washington': 'none', 'wyoming': 'fixed',
    'arkansas': 'fixed', 'california': 'fixed', 'kentucky': 'fixed', 'texas': 'fixed', 'district-of-columbia': 'fixed',
}


def build_wc():
    out = os.path.join(D, 'wc')
    for old in glob.glob(os.path.join(out, '*.json')):
        os.remove(old)
    for f in sorted(glob.glob(os.path.join(R, 'wc', '*.json'))):
        r = jload(f)
        slug = r['slug']
        t = r.get('ttd') or {}
        if t.get('rate') is None:
            skipped.append(f'wc/{slug}: no rate'); continue
        if t.get('max') is None and t.get('maxWeeklyDerived') is not None:
            # Arizona caps the average monthly wage, not the benefit: weekly equivalent of 66 2/3% of the cap.
            t['max'] = t['maxWeeklyDerived']
            t['periodLabel'] = (t.get('periodLabel') or '') + f"; weekly maximum = {t['rate']}% of the maximum average monthly wage ${t.get('maxAverageMonthlyWage'):,.2f} × 12 ÷ 52"
        if t.get('max') is None and t.get('maxMonthly') is not None:
            # Washington and Wyoming publish monthly limits only: weekly equivalents (× 12 ÷ 52).
            t['max'] = round(t['maxMonthly'] * 12 / 52, 2)
            if t.get('min') is None and t.get('minMonthly') is not None:
                t['min'] = round(t['minMonthly'] * 12 / 52, 2)
            t['periodLabel'] = (t.get('periodLabel') or '') + f"; weekly equivalents of the monthly limits (${t['maxMonthly']:,.2f} a month × 12 ÷ 52)"
        if t.get('max') is None and slug in WC_MAX_REQUIRED:
            skipped.append(f'wc/{slug}: the state sets a weekly maximum that could not be read on an official page'); continue
        basis, blabel = wc_basis(t.get('basis'))
        mt = (t.get('minText') or '').lower()
        minpct = None
        if slug in WC_MINRULE:
            minrule = WC_MINRULE[slug]
            if isinstance(minrule, tuple):
                minrule, minpct = minrule
        elif t.get('min') is None:
            minrule = 'none'
        elif re.search(r'(actual|average weekly) (wage|earnings)[^.]{0,40}(less|lower|below)|if (the )?(aww|wage|earnings)[^.]{0,40}(less|lower|below)|or (the employee.s )?(actual )?(full )?wages?,? if (less|lower)', mt):
            minrule = 'actual-wage-if-lower'
        else:
            minrule = 'fixed'
        sources, seen = [], set()
        def addsrc(name, url):
            if url and url not in seen:
                seen.add(url); sources.append({'name': name, 'url': url})
        ag = r.get('agency') or {}
        addsrc(f"{r['name']}: weekly benefit rates ({ag.get('name', 'state agency')})", t.get('url'))
        addsrc(f"{r['name']}: {(r.get('statute') or {}).get('cite', 'statute')}", (r.get('statute') or {}).get('url'))
        addsrc(f"{r['name']}: waiting period", (r.get('waiting') or {}).get('url'))
        addsrc(f"{r['name']}: duration of temporary disability", (r.get('ttdDuration') or {}).get('url'))
        addsrc(f"{r['name']}: permanent disability", (r.get('ppd') or {}).get('url'))
        addsrc(f"{r['name']}: {ag.get('name', 'agency')}", ag.get('url'))
        for fct in r.get('facts') or []:
            addsrc(f"{r['name']}: {host(fct.get('url'))}", fct.get('url'))
        w = r.get('waiting') or {}
        du = r.get('ttdDuration') or {}
        d = {
            'slug': slug, 'name': r['name'], 'abbr': r['abbr'], 'verified': r.get('verified', '2026-10-08'),
            'agency': {'name': ag.get('name', ''), 'url': ag.get('url', '')},
            'ttd': {'rate': t['rate'], 'basis': basis, 'basisLabel': blabel, 'rateText': t.get('rateText', ''),
                    'max': t.get('max'), 'min': t.get('min'), 'minRule': minrule, 'minPct': minpct, 'minText': t.get('minText') or '',
                    'effective': t.get('effective') or t.get('asOf') or '', 'periodLabel': t.get('periodLabel', ''), 'url': t.get('url', '')},
            'waiting': {'days': w.get('days'), 'retroactiveAfterDays': w.get('retroactiveAfterDays'), 'text': w.get('text', ''), 'url': w.get('url', '')},
            'ttdDuration': {'maxWeeks': du.get('maxWeeks'), 'text': du.get('text', ''), 'url': du.get('url', '')},
            'ppd': {'text': (r.get('ppd') or {}).get('text', ''), 'url': (r.get('ppd') or {}).get('url', '')},
            'statute': {'name': (r.get('statute') or {}).get('cite', ''), 'url': (r.get('statute') or {}).get('url', '')},
            'facts': [{'text': x['text'], 'url': x['url']} for x in r.get('facts') or [] if x.get('text') and x.get('url')],
            'sources': sources,
        }
        jdump(d, os.path.join(out, f'{slug}.json'))
    print('wc:', len(glob.glob(os.path.join(out, '*.json'))), 'files')


# ── Alimony ─────────────────────────────────────────────────────────────────────────────────────
def build_alimony():
    out = os.path.join(D, 'alimony')
    for old in glob.glob(os.path.join(out, '*.json')):
        os.remove(old)
    for f in sorted(glob.glob(os.path.join(R, 'alimony', '*.json'))):
        r = jload(f)
        slug = r['slug']
        if not os.path.exists(os.path.join(ROOT, 'src', 'lib', 'engine', 'al', f'{slug}.ts')):
            skipped.append(f'alimony/{slug}: no model file src/lib/engine/al/{slug}.ts'); continue
        fo, du, el = r.get('formula') or {}, r.get('duration') or {}, r.get('eligibility') or {}
        sources, seen = [], set()
        def addsrc(name, url):
            if url and url not in seen:
                seen.add(url); sources.append({'name': name, 'url': url})
        addsrc(f"{r['name']}: support formula", fo.get('url'))
        addsrc(f"{r['name']}: duration", du.get('url'))
        addsrc(f"{r['name']}: eligibility", el.get('url'))
        for fct in r.get('facts') or []:
            addsrc(f"{r['name']}: {host(fct.get('url'))}", fct.get('url'))
        tn = r.get('taxNote') or {}
        if isinstance(tn, dict):
            addsrc('IRS Topic no. 452, Alimony and separate maintenance', tn.get('url'))
        basis = r.get('incomeBasis') or ('net' if 'net' in (fo.get('text') or '').lower()[:200] and 'gross' not in (fo.get('text') or '').lower()[:200] else 'gross')
        d = {
            'slug': slug, 'name': r['name'], 'abbr': r['abbr'], 'verified': r.get('verified', '2026-10-08'),
            'scope': r.get('scope') or '', 'incomeBasis': basis,
            'formulaText': fo.get('text') or '', 'durationText': du.get('text') or '', 'eligibilityText': el.get('text') or '',
            'params': fo.get('params') or {}, 'durationTable': du.get('table'),
            'facts': [{'text': x['text'], 'url': x['url']} for x in r.get('facts') or [] if x.get('text') and x.get('url')],
            'sources': sources, 'testCases': r.get('testCases') or [],
        }
        jdump(d, os.path.join(out, f'{slug}.json'))
    print('alimony:', len(glob.glob(os.path.join(out, '*.json'))), 'files')


# ── Divorce and probate (one array of 51 states each) ──────────────────────────────────────────
def read_array(topic):
    p = os.path.join(R, topic, 'states.json')
    rows = []
    if os.path.exists(p):
        rows = jload(p)
    else:  # work in progress: research/<topic>/parts/*.json (objects or arrays)
        for f in sorted(glob.glob(os.path.join(R, topic, 'parts', '*.json'))):
            x = jload(f)
            rows += x if isinstance(x, list) else [x]
    by = {}
    for r in rows:
        if isinstance(r, dict) and r.get('slug'):
            by[r['slug']] = r
    return [by[k] for k in sorted(by)]


def collect_sources(name, obj):
    out, seen = [], set()
    def walk(label, o):
        if isinstance(o, dict):
            u = o.get('url') or o.get('feeUrl')
            if isinstance(u, str) and u.startswith('http') and u not in seen:
                seen.add(u); out.append({'name': f'{name}: {label}', 'url': u})
            for k, v in o.items():
                if isinstance(v, (dict, list)):
                    walk(LABELS.get(k, k), v)
        elif isinstance(o, list):
            for v in o:
                walk(label, v)
    walk('official page', obj)
    return out


LABELS = {'creditorClaims': 'creditor claims', 'earliestClose': 'closing the estate', 'smallEstate': 'small estates',
          'simplified': 'simplified procedure', 'filingFee': 'filing fee', 'personalRepFee': 'personal representative fees',
          'attorneyFee': 'attorney fees', 'otherFees': 'court fees', 'waiver': 'fee waiver', 'residency': 'residency requirement',
          'waitingPeriod': 'waiting period', 'parentingClass': 'parenting class'}


def build_divorce():
    out = []
    for r in read_array('divorce'):
        d = {k: r.get(k) for k in ('slug', 'name', 'abbr', 'filingFee', 'responseFee', 'feeScope', 'feeText', 'feeUrl', 'otherFees',
                                     'waiver', 'residency', 'waitingPeriod', 'simplified', 'parentingClass')}
        d['verified'] = r.get('verified', '2026-10-08')
        d['otherFees'] = [f for f in (d['otherFees'] or []) if isinstance(f, dict)]
        d['feeScope'] = d['feeScope'] or ''
        d['feeText'] = d['feeText'] or ''
        d['feeUrl'] = d['feeUrl'] or ''
        srcs = collect_sources(r['name'], {'feeUrl': d['feeUrl'], 'url': d['feeUrl']})
        srcs += [x for x in collect_sources(r['name'], {k: d[k] for k in ('otherFees', 'waiver', 'residency', 'waitingPeriod', 'simplified', 'parentingClass')}) if x['url'] not in {y['url'] for y in srcs}]
        if srcs:
            srcs[0]['name'] = f"{r['name']}: court filing fees"
        d['sources'] = srcs
        d['facts'] = []
        out.append(d)
    jdump(out, os.path.join(D, 'divorce.json'))
    print('divorce:', len(out), 'states')


def build_probate():
    out = []
    for r in read_array('probate'):
        d = {k: r.get(k) for k in ('slug', 'name', 'abbr', 'creditorClaims', 'earliestClose', 'smallEstate', 'simplified',
                                     'filingFee', 'personalRepFee', 'attorneyFee')}
        d['verified'] = r.get('verified', '2026-10-08')
        for k in ('creditorClaims', 'smallEstate', 'personalRepFee', 'attorneyFee'):
            d[k] = d[k] or {}
            d[k].setdefault('text', ''); d[k].setdefault('url', '')
        d['creditorClaims'].setdefault('months', None); d['smallEstate'].setdefault('limit', None)
        d['personalRepFee'].setdefault('type', ''); d['attorneyFee'].setdefault('type', '')
        d['sources'] = collect_sources(r['name'], {k: d[k] for k in LABELS if k in d})
        d['facts'] = []
        out.append(d)
    jdump(out, os.path.join(D, 'probate.json'))
    fo = os.path.join(D, 'probate-fees')
    os.makedirs(fo, exist_ok=True)
    # Schedules that apply to other assets than the probate estate (Ohio: real property not sold;
    # Oregon: non-probate property): shown, never added to the estate's total.
    OTHER_BASE = {'ohio': ['R.C. 2113.35(B)'], 'oregon': ['116.173(3)(b)']}
    for f in glob.glob(os.path.join(R, 'probate', 'fees', '*.json')):
        x = jload(f)
        for sc in x.get('schedules', []):
            if any(k in sc.get('who', '') for k in OTHER_BASE.get(x['slug'], [])):
                sc['otherBase'] = True
        jdump(x, os.path.join(fo, os.path.basename(f)))
    print('probate:', len(out), 'states,', len(glob.glob(os.path.join(fo, '*.json'))), 'fee schedules')


